/* ------------------------------------------------------------------ *
 * Graphs chapter — "Shortest Paths: The Ideas": the concept lesson that
 * comes before the Dijkstra / Bellman-Ford / Floyd-Warshall code lessons.
 *
 * No code here on purpose: why BFS is not enough, dist[] and relaxation,
 * Dijkstra by hand (generated by really running it), why negative edges
 * break it, Bellman-Ford's "relax everything again" idea, negative cycles,
 * Floyd-Warshall's "allow one more stop" idea, and when to use which.
 * ------------------------------------------------------------------ */
import { G_W, G_NEGCYCLE, G_FW } from '../../visuals/graphData.js';

const T = (en, bn) => (en === bn ? en : { en, bn });
const scene = (g, extra = {}) => ({ kind: 'graphx', directed: g.directed, weighted: g.weighted, nodes: g.nodes, edges: g.edges, ...extra });
const step = (title, explanation, sc) => ({ title, explanation, scene: sc });
const ek = (u, v) => `${u}-${v}`;
const fmt = (x) => (x === Infinity ? '∞' : String(x));
const N = (list) => list.map(([id, x, y]) => ({ id, label: String(id), x, y }));
const allEdges = (g, st) => Object.fromEntries(g.edges.map((e) => [ek(e.u, e.v), st]));
const keyOf = (g, u, v) => (g.edges.some((e) => e.u === u && e.v === v) ? ek(u, v) : ek(v, u));
const subsOf = (dist) => Object.fromEntries(dist.map((d, i) => [i, fmt(d)]));
const distPanel = (dist, hl = {}, label = T('dist[ ] — best distance found so far', 'dist[ ] — এ পর্যন্ত পাওয়া সেরা দূরত্ব')) => ({ type: 'array', label, cells: dist.map(fmt), hl });

/* --------------------------------------------------------------- example graphs */

// BFS counts edges, not kilometres: the direct road 0–2 is long
const G_BFS = {
  V: 3,
  directed: false,
  weighted: true,
  nodes: N([[0, 80, 220], [1, 260, 60], [2, 440, 220]]),
  edges: [{ u: 0, v: 1, w: 1 }, { u: 1, v: 2, w: 1 }, { u: 0, v: 2, w: 5 }]
};

// one negative edge is enough to fool Dijkstra
const G_NEG = {
  V: 3,
  directed: true,
  weighted: true,
  nodes: N([[0, 80, 170], [1, 330, 60], [2, 330, 280]]),
  edges: [{ u: 0, v: 1, w: 2 }, { u: 0, v: 2, w: 3 }, { u: 2, v: 1, w: -2 }]
};
// the same graph with the edge list in an unlucky order, for Bellman-Ford's passes
const G_NEG_ORDER = { ...G_NEG, edges: [G_NEG.edges[2], G_NEG.edges[0], G_NEG.edges[1]] };

/* --------------------------------------------------------------- Dijkstra by hand */

function dijkstraRounds(g, src) {
  const adj = Array.from({ length: g.V }, () => []);
  for (const e of g.edges) { adj[e.u].push({ v: e.v, w: e.w }); if (!g.directed) adj[e.v].push({ v: e.u, w: e.w }); }
  const dist = Array(g.V).fill(Infinity);
  const parent = Array(g.V).fill(-1);
  const done = Array(g.V).fill(false);
  dist[src] = 0;
  const rounds = [];
  for (let r = 0; r < g.V; r++) {
    let u = -1;
    for (let i = 0; i < g.V; i++) if (!done[i] && (u === -1 || dist[i] < dist[u])) u = i;
    if (u === -1 || dist[u] === Infinity) break;
    const before = [...dist];
    const doneBefore = [...done];
    done[u] = true;
    const relax = [];
    for (const { v, w } of adj[u]) {
      if (done[v]) continue;
      const offer = dist[u] + w;
      const better = offer < dist[v];
      relax.push({ v, w, offer, old: dist[v], better });
      if (better) { dist[v] = offer; parent[v] = u; }
    }
    rounds.push({ u, before, doneBefore, relax, after: [...dist], parent: [...parent], done: [...done] });
  }
  return { rounds, dist, parent };
}

function dijkstraSteps(g, src) {
  const { rounds, dist, parent } = dijkstraRounds(g, src);
  const out = [];
  rounds.forEach((r, i) => {
    const cand = r.doneBefore.map((d, v) => (!d ? `dist[${v}] = ${fmt(r.before[v])}` : null)).filter(Boolean).join(', ');
    const relaxEn = r.relax.length
      ? r.relax.map((x) => `- ${r.u} → ${x.v}: ${fmt(r.before[r.u])} + ${x.w} = **${x.offer}** ${x.better ? `< ${fmt(x.old)} → dist[${x.v}] = ${x.offer} ✓` : `≥ ${fmt(x.old)} → keep ${fmt(x.old)}`}`).join('\n')
      : '- no unfinished neighbours';
    const relaxBn = r.relax.length
      ? r.relax.map((x) => `- ${r.u} → ${x.v}: ${fmt(r.before[r.u])} + ${x.w} = **${x.offer}** ${x.better ? `< ${fmt(x.old)} → dist[${x.v}] = ${x.offer} ✓` : `≥ ${fmt(x.old)} → ${fmt(x.old)}-ই থাকুক`}`).join('\n')
      : '- শেষ-না-হওয়া কোনো প্রতিবেশী নেই';
    const edgeState = allEdges(g, 'dim');
    for (let v = 0; v < g.V; v++) if (r.parent[v] >= 0) edgeState[keyOf(g, r.parent[v], v)] = r.done[v] ? 'tree' : 'frontier';
    for (const x of r.relax) edgeState[keyOf(g, r.u, x.v)] = x.better ? 'relax' : 'compare';
    const nodeState = {};
    r.done.forEach((d, v) => { if (d) nodeState[v] = 'done'; });
    nodeState[r.u] = 'current';
    out.push(step(
      T(`Dijkstra by hand, round ${i + 1}: ${r.u} is final (${fmt(r.before[r.u])})`, `হাতে-কলমে ডাইকস্ট্রা, রাউন্ড ${i + 1}: ${r.u} চূড়ান্ত (${fmt(r.before[r.u])})`),
      T(
        `${i === 0 ? `Start: \`dist[${src}] = 0\`, everyone else **∞** (not reached yet).\n\n` : ''}Unfinished: ${cand}. The smallest is **${r.u}** (${fmt(r.before[r.u])}) → its distance is now **final**.\n\nThen relax the edges out of ${r.u}:\n${relaxEn}`,
        `${i === 0 ? `শুরু: \`dist[${src}] = 0\`, বাকি সবাই **∞** (এখনো পৌঁছানো হয়নি)।\n\n` : ''}শেষ-না-হওয়া: ${cand}। সবচেয়ে ছোট **${r.u}** (${fmt(r.before[r.u])}) → এর দূরত্ব এখন **চূড়ান্ত**।\n\nতারপর ${r.u} থেকে বের হওয়া এজগুলো রিল্যাক্স করো:\n${relaxBn}`
      ),
      scene(g, { nodeState, edgeState, edgeFrom: Object.fromEntries(r.relax.map((x) => [keyOf(g, r.u, x.v), r.u])), subs: subsOf(r.after), tags: { [src]: 'start' }, panels: [distPanel(r.after, { [r.u]: 'current', ...Object.fromEntries(r.relax.filter((x) => x.better).map((x) => [x.v, 'relax'])) })], status: T(`${r.u} final · dist = [${r.after.map(fmt).join(', ')}]`, `${r.u} চূড়ান্ত · dist = [${r.after.map(fmt).join(', ')}]`) })
    ));
  });
  return { steps: out, dist, parent };
}

/* --------------------------------------------------------------- the lesson */

const dij = dijkstraSteps(G_W, 0);
const pathTo = (parent, v) => { const p = []; for (let x = v; x !== -1; x = parent[x]) p.unshift(x); return p.join(' → '); };
const SPT = dij.parent.map((p, v) => (p >= 0 ? [p, v] : null)).filter(Boolean);

// Dijkstra on G_NEG: it finalises 1 at distance 2, but 0 → 2 → 1 costs 1
const negDij = dijkstraRounds(G_NEG, 0);

// Bellman-Ford passes on the unlucky edge order
function bfPasses(g, src) {
  const dist = Array(g.V).fill(Infinity);
  dist[src] = 0;
  const passes = [];
  for (let p = 0; p < g.V - 1; p++) {
    const rows = [];
    let changed = false;
    for (const e of g.edges) {
      const du = dist[e.u];
      const offer = du === Infinity ? Infinity : du + e.w;
      const better = offer < dist[e.v];
      rows.push({ e, du, offer, old: dist[e.v], better });
      if (better) { dist[e.v] = offer; changed = true; }
    }
    passes.push({ rows, dist: [...dist], changed });
    if (!changed) break;
  }
  return passes;
}
const bf = bfPasses(G_NEG_ORDER, 0);
const bfRows = (pass, lang) => pass.rows.map((r) => `- ${r.e.u} → ${r.e.v} (${r.e.w}): ${r.du === Infinity ? `dist[${r.e.u}] = ∞ → ${lang === 'bn' ? 'কিছু করার নেই' : 'nothing to offer'}` : `${r.du} + (${r.e.w}) = **${r.offer}** ${r.better ? `< ${fmt(r.old)} → dist[${r.e.v}] = ${r.offer} ✓` : `≥ ${fmt(r.old)} → ${lang === 'bn' ? 'থাকুক' : 'keep'}`}`}`).join('\n');

